# ╔═╡ b09e1e48-494e-4967-826a-6e70199acad4
md"""
### Squashed Gaussian Alternative
"""

# ╔═╡ 5864a5a3-a5a5-43c2-9cb4-7d13b2d20bed
md"""
Normal Distribution: $f(x) = \frac{1}{\sqrt{2 \pi \sigma^2}} e^{- \frac{(x - \mu)^2}{2 \sigma^2}}$

Consider a new random variable $Y \sim \tanh(X)$ where $X \sim N(0, 1)$.  Using the change of variables theorem from probability theory we can compute the density function of $Y$:

$f_Y(y) = f_X (g^{-1}(y)) \cdot \left \vert \frac{d}{dy} g^{-1}(y) \right \vert$

where $g(x) = \tanh(x) = \frac{e^x - e^{-x}}{e^x + e^{-x}}$ so $f_Y(y) = \frac{1}{\sqrt{2 \pi \sigma^2}} e^{- \frac{\left (\tanh^{-1}(y) - \mu \right )^2}{2 \sigma^2}} \left \vert \frac{1}{1 - y^2} \right \vert$
"""

# ╔═╡ 94517664-6988-44dc-a297-e9d5873ee540
#=╠═╡
@bind squashed_gaussian_plot_params PlutoUI.combine() do Child
	md"""
	### Squashed Gaussian Plot Parameters
	 $$\mu$$: $(Child(Slider(-4:.1:4, default = 0, show_value=true)))
	
	 $$\sigma$$: $(Child(Slider(0.1:0.1:2, default = .5, show_value=true)))

	maximum value: $(Child(Slider(.1:0.1:2., default = 1, show_value=true)))
	"""
end
  ╠═╡ =#

# ╔═╡ b16899b7-36bf-4a5e-8e2f-4496b8450687
squashed_gaussian_pdf(x::Union{T, AbstractArray{N, T}}, μ::T, σ::T, xmax::T) where {N, T<:Real} = inv(σ*sqrt(T(2)*π)) * exp(-inv(T(2))*((atanh(x/xmax) - μ)/σ)^2) / abs(xmax*(1 - (x/xmax)^2))

# ╔═╡ 00bd2835-b006-4244-9877-bc7e031e3ef8
#=╠═╡
function plot_squashed_gaussian(μ::T, σ::T, xmax::T; npoints = 1000) where T<:Real
	x = LinRange(-one(T)*xmax, one(T)*xmax, npoints)
	y = squashed_gaussian_pdf.(x, μ, σ, xmax)
	plot(x, y, Layout(xaxis_range = [-2, 2]))
end
  ╠═╡ =#

# ╔═╡ 3e7cecec-eb77-4862-8e3c-b510422e06db
#=╠═╡
plot_squashed_gaussian(squashed_gaussian_plot_params...)
  ╠═╡ =#

# ╔═╡ 78c83673-2117-4542-b4d8-1c243e8f610b
md"""
#### Eligibility Vector

Recall for the gaussian case and linear approximation we had:

$\begin{flalign}
\pi(a \vert s, \boldsymbol{\theta}) &= \frac{1}{\sqrt{2 \pi \sigma(s, \boldsymbol{\theta})^2}} \exp \left ( - \frac{(a - \mu(s, \boldsymbol{\theta}))^2}{2 \sigma(s, \boldsymbol{\theta})^2} \right )\\
\mu(s, \boldsymbol{\theta}) & \doteq \boldsymbol{\theta}_\mu ^ \top \mathbf{x}_\mu(s) \\
\sigma(s, \boldsymbol{\theta}) & \doteq \exp \left ( \boldsymbol{\theta}_\sigma ^ \top \mathbf{x}_\sigma(s) \right ) \\
\nabla \ln \pi(a \vert s, \boldsymbol{\theta}_\mu) &= \frac{1}{\sigma(s, \boldsymbol{\theta})^2} \left ( a - \mu(s, \boldsymbol{\theta}) \right ) \mathbf{x}_\mu(s) \\
\nabla \ln \pi(a \vert s, \boldsymbol{\theta}_\sigma) &= \left (\frac{(a - \mu(s, \boldsymbol{\theta}))^2}{\sigma(s, \boldsymbol{\theta})^2} \right )\mathbf{x}_\sigma(s) \\
\end{flalign}$

For the squashed gaussian we can apply the previous results to the new pdf:

$\begin{flalign}
\pi(a \vert s, \boldsymbol{\theta}) &= \frac{1}{\sqrt{2 \pi \sigma(s, \boldsymbol{\theta})^2}} \exp \left ( - \frac{(\tanh^{-1}(a) - \mu(s, \boldsymbol{\theta}))^2}{2 \sigma(s, \boldsymbol{\theta})^2} \right ) \left \vert \frac{1}{1 - a^2} \right \vert\\
\mu(s, \boldsymbol{\theta}) & \doteq \boldsymbol{\theta}_\mu ^ \top \mathbf{x}_\mu(s) \\
\sigma(s, \boldsymbol{\theta}) & \doteq \exp \left ( \boldsymbol{\theta}_\sigma ^ \top \mathbf{x}_\sigma(s) \right ) \\
\nabla \ln \pi(a \vert s, \boldsymbol{\theta}_\mu) &= \frac{1}{\sigma(s, \boldsymbol{\theta})^2} \left ( \tanh^{-1}(a) - \mu(s, \boldsymbol{\theta}) \right ) \mathbf{x}_\mu(s) \\
\nabla \ln \pi(a \vert s, \boldsymbol{\theta}_\sigma) &= \left (\frac{(\tanh^{-1}(a) - \mu(s, \boldsymbol{\theta}))^2}{\sigma(s, \boldsymbol{\theta})^2} \right )\mathbf{x}_\sigma(s) \\
\end{flalign}$

"""

# ╔═╡ ae0f5a96-7a4b-47f9-be1e-e803a238a071
md"""
### *MDP Types and Transitions for Continuous Actions*
"""

# ╔═╡ c8b47eac-2d45-419a-bec6-2ae0cdc59393
begin
	#represents a transition where the state must be referenced directly instead of through a tabular index
	abstract type AbstractContinuousTransition{T<:Real, S, A, F<:Function} <: AbstractTransition{T, 2} end
			
	struct ContinuousMDPTransitionSampler{T <: Real, S, A, F <: Function} <: AbstractContinuousTransition{T, S, A, F}
		step::F
		function ContinuousMDPTransitionSampler(step::F, s::S, a::A) where {F<:Function, S, A}
			(r, s′) = step(s, a)
			@assert promote_type(S, typeof(s′)) != Any "There is no common type between the provided state $s and the transition state $s′"
			new{typeof(r), promote_type(S, typeof(s′)), A, F}(step)
		end
	end

	#when used as a functor just apply the step function to the state action pair indices
	(ptf::ContinuousMDPTransitionSampler{T, S, A, F})(s::S, a::A) where {T<:Real, S, A, F<:Function} = ptf.step(s, a)
end

# ╔═╡ 537270ba-122b-4f2b-880b-31d086766295
begin
	#the following struct represents a problem for which both the state and action space can take arbitrary values
	struct ContinuousMDP{T<:Real, S, A, P<:AbstractContinuousTransition{T, S, A, F} where F<:Function, StateInit<:Function, IsTerm<:Function, ValidAction <: Function}  <: AbstractMDP{T, S, A, P, StateInit}
		ptf::P
		initialize_state::StateInit #function which provides an initial state index
		isterm::IsTerm #function that returns true if a state is terminal and false otherwise
		is_valid_action::ValidAction #is_valid_action(s, a) returns true if the action a is valid to take from state. by default every action is assumed to be available
		ContinuousMDP(ptf::P, initialize_state::F1, isterm::F2, is_valid_action::F3) where {T<:Real, S, A, F<:Function, P<:AbstractContinuousTransition{T, S, A, F}, F1<:Function, F2<:Function, F3<:Function} = new{T, S, A, P, F1, F2, F3}(ptf, initialize_state, isterm, is_valid_action)
	end

	ContinuousMDP(ptf::AbstractContinuousTransition{T, S, A, F}, initialize_state::StateInit; isterm::Function = Returns(false), is_valid_action::Function = Returns(true)) where {T<:Real, S, A, F<:Function, StateInit<:Function} = ContinuousMDP(ptf, initialize_state, isterm, is_valid_action)

	function ContinuousMDP(step::Function, initialize_state::Function, a::A; kwargs...) where A
		s0 = initialize_state()
		ptf = ContinuousMDPTransitionSampler(step, s0, a)
		ContinuousMDP(ptf, initialize_state; kwargs...)
	end
end

# ╔═╡ 10cdd16e-a337-4421-a7a0-6de4e4b60c0f
begin
	mutable struct BinaryGaussianEligibilityVector{T<:Real, A<:Union{T, NTuple{N, T} where N}, P<:Union{T, Vector{T}}, B <: BinaryFeatureVector}
		binary_features::B
		a::A
		μ::P
		σ::P
	end
	BinaryGaussianEligibilityVector(num_features::Integer, a::T) where T<:Real = BinaryGaussianEligibilityVector(BinaryFeatureVector(num_features), a, zero(T), one(T))
	BinaryGaussianEligibilityVector(num_features::Integer, a::NTuple{N, T}) where {T<:Real, N} = BinaryGaussianEligibilityVector(BinaryFeatureVector(num_features), a, zeros(T, N), ones(T, N))
end

# ╔═╡ 54fff14b-cf53-47b0-9cfa-8b9ee33df54e
begin
	mutable struct BinaryBetaEligibilityVector{T<:Real, A<:Union{T, NTuple{N, T} where N}, P<:Union{T, Vector{T}}, B <: BinaryFeatureVector}
		binary_features::B
		a::A
		α::P
		β::P
	end
	BinaryBetaEligibilityVector(num_features::Integer, a::T) where T<:Real = BinaryBetaEligibilityVector(BinaryFeatureVector(num_features), a, one(T), one(T))
	BinaryBetaEligibilityVector(num_features::Integer, a::NTuple{N, T}) where {T<:Real, N} = BinaryBetaEligibilityVector(BinaryFeatureVector(num_features), a, ones(T, N), ones(T, N))
end

# ╔═╡ 76fd79a2-2bc8-45f8-a243-48415118898a
begin
	mutable struct BinarySquashedGaussianEligibilityVector{T<:Real, A<:Union{T, NTuple{N, T} where N}, P<:Union{T, Vector{T}}, B <: BinaryFeatureVector}
		binary_features::B
		a::A
		μ::P
		σ::P
		amax::A
	end
	BinarySquashedGaussianEligibilityVector(num_features::Integer, a::T, amax::T) where T<:Real = BinarySquashedGaussianEligibilityVector(BinaryFeatureVector(num_features), a, zero(T), one(T), amax)
	BinarySquashedGaussianEligibilityVector(num_features::Integer, a::NTuple{N, T}) where {T<:Real, N} = BinarySquashedGaussianEligibilityVector(BinaryFeatureVector(num_features), a, zeros(T, N), ones(T, N), amax)
end

# ╔═╡ 87ee21f3-16ca-4c8c-a0b9-f9e2fd258a91
md"""
### *REINFORCE Implementation for Continuous Action Spaces*
"""

# ╔═╡ b966b248-fb4d-457d-90f6-114370846242
begin
	bad_continuous_action(a) = false
	bad_continuous_action(a::Real) = isnan(a)
	bad_continuous_action(a::NTuple{N, T}) where {N, T<:Real} = any(bad_continuous_action, a)
end

# ╔═╡ f946c886-6246-4f98-a96f-f06984691ad8
begin
	function ApproximationUtils.runepisode!((states, actions, rewards)::Tuple{Vector{S}, Vector{A}, Vector{T}}, mdp::ContinuousMDP{T, S, A, P, F1, F2, F3}, π::Function; s0::S = mdp.initialize_state(), a0::A = π(s0), max_steps = typemax(Int64)) where {T<:Real, S, A, P, F1<:Function, F2<:Function, F3<:Function}
		s = s0
		l = length(states)
		@assert l == length(actions) == length(rewards)
	
		function add_value!(v, x, i) 
			if i > l
				push!(v, x)
			else
				v[i] = x
			end
		end 
		add_value!(states, s, 1)
		a = a0
		# @info "Selected action is $a"
		(r, s′) = mdp.ptf(s, a0)
		add_value!(actions, a, 1)
		add_value!(rewards, r, 1)
		step = 2
		sterm = s
		if mdp.isterm(s′)
			sterm = s′
		else
			sterm = s
		end
		s = s′
	
		#note that the terminal state will not be added to the state list
		while !mdp.isterm(s) && (step <= max_steps)
			add_value!(states, s, step)
			a = π(s)
			if bad_continuous_action(a)
				@info "Terminating episode after $step steps due to bad continuous action $a taken in state $s"
				step = 1
				break
			end
			# @info "Selected action is $a"
			(r, s′) = mdp.ptf(s, a)
			add_value!(actions, a, step)
			add_value!(rewards, r, step)
			s = s′
			step += 1
			if mdp.isterm(s′)
				sterm = s′
			end
		end
		return states, actions, rewards, sterm, step-1
	end
	
	function ApproximationUtils.runepisode(mdp::ContinuousMDP{T, S, A, P, F1, F2, F3}, π::Function; kwargs...) where {T<:Real, S, A, P, F1, F2, F3}
		states = Vector{S}()
		actions = Vector{A}()
		rewards = Vector{T}()
		runepisode!((states, actions, rewards), mdp, π; kwargs...)
	end

	ApproximationUtils.runepisode(mdp::ContinuousMDP{T, S, A, P, F1, F2, F3}; kwargs...) where {T<:Real, S, N, A <: Union{T, NTuple{N, T}}, P, F1, F2, F3} = runepisode(mdp, Returns(rand(A)); kwargs...)
end

# ╔═╡ f7433324-acc3-49a5-b5b3-ada0c8f09d52
#=╠═╡
runepisode(corridor_mdp)
  ╠═╡ =#

# ╔═╡ fb8904a9-ae64-41cc-93b6-5a25855edad0
#=╠═╡
function get_corridor_episode_stats(p::Real; ntrials=10_000)
	1:ntrials |> Map(_ -> runepisode(corridor_mdp; π = s -> (rand() < p) + 1) |> first |> length) |> foldxt(+) |> a -> a / ntrials
end
  ╠═╡ =#

# ╔═╡ cecc2a35-3850-4f66-84e8-e29da4f3d4b0
#=╠═╡
function get_corridor_episode_stats(π::Function; make_policy_kwargs::Function = () -> NamedTuple(), ntrials=10_000, kwargs...)
	1:ntrials |> Map() do _ 
		policy_kwargs = make_policy_kwargs()
		runepisode(corridor_mdp; π = s -> π(s; policy_kwargs...), kwargs...)  |> first |> length
	end |> foldxt(+) |> a -> a / ntrials
end
