# ╔═╡ bba13634-ff0e-47f7-a23b-8d56098f4ac6
begin
	function gaussian_action_sampler(params::Vector{T}) where T<:Real 
		σ = exp(params[2])
		μ = params[1]
		isinf(μ) && return μ
		isapprox(σ, zero(T)) && return μ
		isnan(σ) && return μ
		rand(Normal(μ, σ))
	end
	make_gaussian_n_sampler(::Val{1}) = gaussian_action_sampler
	function make_gaussian_n_sampler(::Val{N}) where N
		function f(params::Vector{T}) where T<:Real
			ntuple(i -> rand(Normal(params[i], exp(params[i+N]))), N)
		end
	end

	make_gaussian_n_sampler(n::Integer) = make_gaussian_n_sampler(Val(n))

	make_gaussian_sampler(::T) where T<:Real = gaussian_action_sampler
	make_gaussian_sampler(::NTuple{N, T}) where {N, T<:Real} = make_gaussian_n_sampler(N)
end

# ╔═╡ b2082ab0-73a4-45a6-8772-a2e6e22b519a
begin
	function beta_action_sampler(p1::T, p2::T) where T<:Real
		isnan(p1) && return p1
		isnan(p2) && return p2
		ϵ = eps(zero(T))
		α = max(ϵ, exp(p1))
		β = max(ϵ, exp(p2))
		T(rand(Beta(α, β)))
	end
	beta_action_sampler(params::Vector{T}) where T<:Real = beta_action_sampler(params[1], params[2])
	make_beta_n_sampler(::Val{1}) = beta_action_sampler
	function make_beta_n_sampler(::Val{N}) where N
		function f(params::Vector{T}) where T<:Real
			ntuple(i -> beta_action_sampler(params[i], params[i+N]), N)
		end
	end

	make_beta_n_sampler(n::Integer) = make_beta_n_sampler(Val(n))

	make_beta_sampler(::T) where T<:Real = beta_action_sampler
	make_beta_sampler(::NTuple{N, T}) where {N, T<:Real} = make_beta_n_sampler(N)
end

# ╔═╡ 7a6f3f79-ea06-4994-8b62-90b2056e4034
begin
	function squashed_gaussian_action_sampler(params::Vector{T}, amax::T) where T<:Real 
		σ = exp(params[2])
		μ = params[1]
		isinf(μ) && return amax*sign(μ)
		isapprox(σ, zero(T)) && return amax*tanh(μ)
		isnan(σ) && return amax*tanh(μ)
		amax*tanh(rand(Normal(μ, σ)))
	end
	make_squashed_gaussian_n_sampler(::Val{1}, amax::T) where T<:Real = params -> squashed_gaussian_action_sampler(params, amax)
	function make_squashed_gaussian_n_sampler(::Val{N}, amax::NTuple{N, T}) where {N, T<:Real}
		function f(params::Vector{T}) where T<:Real
			ntuple(i -> amax[i]*tanh(rand(Normal(params[i], exp(params[i+N])))), N)
		end
	end

	make_squashed_gaussian_n_sampler(n::Integer, amax::T) where T<:Real = make_squashed_gaussian_n_sampler(Val(n), amax)

	make_squashed_gaussian_sampler(::T, amax::T) where T<:Real = params -> squashed_gaussian_action_sampler(params, amax)
	make_squashed_gaussian_sampler(::NTuple{N, T}, amax::NTuple{N, T}) where {N, T<:Real} = make_squashed_gaussian_n_sampler(N, amax)
end

# ╔═╡ 5261651e-a51e-4e80-8e23-83a4c10e5259
begin
	function update_gaussian_eligibility_vector!(∇lnπ::Matrix{T}, action_dist_params::Vector{T}, x::Vector{T}, action::T, policy_params::Matrix{T}) where T<:Real
		c1 = action - first(action_dist_params)
		σ = exp(last(action_dist_params))
		c2 = σ^-2
		c3 = c2*c1
		c4 = c3*c1 - one(T)
		@inbounds @simd for i in eachindex(x)
			∇lnπ[i, 1] = x[i]*c3
		end

		@inbounds @simd for i in eachindex(x)
			∇lnπ[i, 2] =  x[i]*c4
		end
	end

	function update_gaussian_eligibility_vector!(∇lnπ::Matrix{T}, action_dist_params::Vector{T}, x::Vector{T}, action::NTuple{N, T}, policy_params::Matrix{T}) where {N, T <: Real}
		for k = 1:N
			c1 = action - action_dist_params[k]
			σ = exp(action_dist_params[k+N])
			c2 = σ^-2
			c3 = c2*c1
			c4 = c3*c1 - one(T)
			@inbounds @simd for i in eachindex(x)
				∇lnπ[i, k] = x[i]*c3
			end
	
			@inbounds @simd for i in eachindex(x)
				∇lnπ[i, k+N] = x[i]*c4
			end
		end
	end
end

# ╔═╡ bfe7e41d-6318-4bd4-b892-287831876abc
begin
	function update_beta_eligibility_vector!(∇lnπ::Matrix{T}, action_dist_params::Vector{T}, x::Vector{T}, action::T, policy_params::Matrix{T}) where T<:Real
		α = exp(first(action_dist_params))
		β = exp(last(action_dist_params))
		c1 = digamma(α + β)
		δ1 = (log(action) + c1 - digamma(α))*α
		@inbounds @simd for i in eachindex(x)
			∇lnπ[i, 1] = x[i]*δ1
		end

		δ2 = (log(one(T) - action) + c1 - digamma(β))*β
		@inbounds @simd for i in eachindex(x)
			∇lnπ[i, 2] =  x[i]*δ2
		end
	end

	function update_beta_eligibility_vector!(∇lnπ::Matrix{T}, action_dist_params::Vector{T}, x::Vector{T}, action::NTuple{N, T}, policy_params::Matrix{T}) where {N, T <: Real}
		for k = 1:N
			α = exp(action_dist_params[k])
			β = exp(action_dist_params[k+N])
			c1 = digamma(α + β)
			δ1 = (log(action[k]) + c1 - digamma(α))*α
			@inbounds @simd for i in eachindex(x)
				∇lnπ[i, k] = x[i]*δ1
			end

			δ2 = (log(one(T) - action[k]) + c1 - digamma(β))*β
			@inbounds @simd for i in eachindex(x)
				∇lnπ[i, k+N] = x[i]*δ2
			end
		end
	end
end

# ╔═╡ 6bf5ad39-1400-4e1f-a843-a1934b8aaa48
begin
	function update_squashed_gaussian_eligibility_vector!(∇lnπ::Matrix{T}, action_dist_params::Vector{T}, x::Vector{T}, action::T, policy_params::Matrix{T}, amax::T) where T<:Real
		c1 = atanh(action/amax) - first(action_dist_params)
		σ = exp(last(action_dist_params))
		c2 = σ^-2
		c3 = c2*c1
		c4 = c3*c1 - one(T)
		@inbounds @simd for i in eachindex(x)
			∇lnπ[i, 1] = x[i]*c3
		end

		@inbounds @simd for i in eachindex(x)
			∇lnπ[i, 2] =  x[i]*c4
		end
	end

	function update_squashed_gaussian_eligibility_vector!(∇lnπ::Matrix{T}, action_dist_params::Vector{T}, x::Vector{T}, action::NTuple{N, T}, policy_params::Matrix{T}, amax::NTuple{N, T}) where {N, T <: Real}
		for k = 1:N
			c1 = atanh(action/amax[k]) - action_dist_params[k]
			σ = exp(action_dist_params[k+N])
			c2 = σ^-2
			c3 = c2*c1
			c4 = c3*c1 - one(T)
			@inbounds @simd for i in eachindex(x)
				∇lnπ[i, k] = x[i]*c3
			end
	
			@inbounds @simd for i in eachindex(x)
				∇lnπ[i, k+N] = x[i]*c4
			end
		end
	end
end

# ╔═╡ f55afa58-962d-4551-8d95-a5b467d61adf
begin
	function update_params_with_gradient!(θ::Matrix{T}, α::T, ∇θ::BinaryGaussianEligibilityVector{T, T, T, B}) where {T<:Real, B<:BinaryFeatureVector}
		c1 = ∇θ.a - ∇θ.μ
		c2 = ∇θ.σ^(-2)
		# isnan(c2) && @info "warning σ of $∇θ.σ is causing nan results"
		# isinf(c2) && @info "warning σ of $∇θ.σ is causing inf results"
		c3 = c1 * c2
		c4 = c3*c1 - one(T)
		δ1 = α*c3
		@inbounds @simd for j in 1:∇θ.binary_features.num_features
			i = ∇θ.binary_features.active_features[j]
			θ[i, 1] += δ1
		end
	
		δ2 = α*c4
		@inbounds @simd for j in 1:∇θ.binary_features.num_features
			i = ∇θ.binary_features.active_features[j]
			θ[i, 2] += δ2
		end
		return θ
	end

	function update_params_with_gradient!(θ::Matrix{T}, α::T, ∇θ::BinaryBetaEligibilityVector{T, T, T, B}) where {T<:Real, B<:BinaryFeatureVector}
		c1 = digamma(∇θ.α + ∇θ.β)
		δ1 = α*(log(∇θ.a) + c1 - digamma(∇θ.α))
		@inbounds @simd for j in 1:∇θ.binary_features.num_features
			i = ∇θ.binary_features.active_features[j]
			θ[i, 1] += δ1
		end
	
		δ2 = α*(log(one(T) - ∇θ.a) + c1 - digamma(∇θ.β))
		@inbounds @simd for j in 1:∇θ.binary_features.num_features
			i = ∇θ.binary_features.active_features[j]
			θ[i, 2] += δ2
		end
		return θ
	end

		function update_params_with_gradient!(θ::Matrix{T}, α::T, ∇θ::BinarySquashedGaussianEligibilityVector{T, T, T, B}) where {T<:Real, B<:BinaryFeatureVector}
		c1 = atanh(∇θ.a/∇θ.amax) - ∇θ.μ
		c2 = ∇θ.σ^(-2)
		# isnan(c2) && @info "warning σ of $∇θ.σ is causing nan results"
		# isinf(c2) && @info "warning σ of $∇θ.σ is causing inf results"
		c3 = c1 * c2
		c4 = c3*c1 - one(T)
		δ1 = α*c3
		@inbounds @simd for j in 1:∇θ.binary_features.num_features
			i = ∇θ.binary_features.active_features[j]
			θ[i, 1] += δ1
		end
	
		δ2 = α*c4
		@inbounds @simd for j in 1:∇θ.binary_features.num_features
			i = ∇θ.binary_features.active_features[j]
			θ[i, 2] += δ2
		end
		return θ
	end

	function update_params_with_gradient!(θ::Matrix{T}, α::T, ∇θ::BinaryGaussianEligibilityVector{T, NTuple{N, T}, Vector{T}, B}) where {T<:Real, N, B<:BinaryFeatureVector}
		for k in 1:N
			c1 = ∇θ.a[k] - ∇θ.μ[k]
			c2 = ∇θ.σ[k] ^-2
			# isnan(c2) && @info "warning σ of $∇θ.σ is causing nan results"
			# isinf(c2) && @info "warning σ of $∇θ.σ is causing inf results"
			c3 = c1 * c2
			c4 = c3*c1 - one(T)
			δ1 = α*c3
			@inbounds @simd for i in 1:size(θ, 1)
				θ[i, k] += δ1
			end
		
			δ2 = α*c4
			@inbounds @simd for i in 1:size(θ, 1)
				θ[i, k+N] += δ2
			end
		end
		return θ
	end

	function update_params_with_gradient!(θ::Matrix{T}, α::T, ∇θ::BinaryBetaEligibilityVector{T, NTuple{N, T}, Vector{T}, B}) where {T<:Real, N, B<:BinaryFeatureVector}
		for k in 1:N
			c1 = digamma(∇θ.α[k] + ∇θ.β[k])
			δ1 = α*(log(∇θ.a[k]) + c1 - digamma(∇θ.α[k]))
			@inbounds @simd for i in 1:size(θ, 1)
				θ[i, k] += δ1
			end
		
			δ2 = α*(log(one(T) - ∇θ.a[k]) + c1 - digamma(∇θ.β[k]))
			@inbounds @simd for i in 1:size(θ, 1)
				θ[i, k+N] += δ2
			end
		end
		return θ
	end
end

# ╔═╡ 4fb83451-b6f8-4e6e-a131-1accc8e10b08
#version of reinforce for general function approximation
function reinforce_with_baseline_monte_carlo_control!(policy_params, value_params, mdp::StateMDP{T, S, A, PTF, F1, F2, F3}, γ::T, num_episodes::Integer, feature_vector, update_feature_vector!::Function, value_function::Function, ∇v̂, update_value_gradient!::Function, ∇lnπ; α_w::T = one(T)/10, α_θ::T = one(T)/10, max_steps = typemax(Int64), use_unfinished_episodes::Bool = false, eligibility_update_kwargs...) where {T<:Real, S, A, PTF, F1, F2, F3}
	rewards = Vector{Union{T, Missing}}(undef, num_episodes)
	steps = Vector{Union{Int64, Missing}}(undef, num_episodes)

	policy_and_value_components = form_policy_and_value_function(mdp, feature_vector, update_feature_vector!, policy_params, value_params)

	policy = zeros(T, length(mdp.actions))
	policy_args = form_policy_args(policy_params)
	function π_sample(s::S)
		update_feature_vector!(feature_vector, s)
		update_policy_dist!(policy, feature_vector, policy_params, policy_args...)
		sample_action(policy)
	end
	
	state_history, action_history, reward_history, _, _ = runepisode(mdp; π = π_sample, max_steps = 0) #initialize variables to update episodes
	for ep in eachindex(rewards)
		# @info "On episode $i of $max_episodes"
		state_history, action_history, reward_history, sterm, nsteps = runepisode!((state_history, action_history, reward_history), mdp; π = π_sample, max_steps = max_steps)
		if mdp.isterm(sterm) || use_unfinished_episodes #only update value function if an episode terminated in a terminal state successfully
			g = zero(T)
			rtotal = zero(T)
			#iterate through episode beginning at the end
			for i in nsteps:-1:1
				g = (γ * g) + reward_history[i]
				update_feature_vector!(feature_vector, state_history[i])
				v̂ = value_function(feature_vector, value_params)
				δ = g - v̂
				update_value_gradient!(∇v̂, feature_vector, value_params)
				c = α_w*δ
				update_params_with_gradient!(value_params, c, ∇v̂)
				# @info "Updating eligiblity vector $∇lnπ with action $(action_history[i])"
				update_eligibility_vector!(∇lnπ, feature_vector, action_history[i], policy_params; eligibility_update_kwargs...)
				c = α_θ * γ^(i-1) * δ
				update_params_with_gradient!(policy_params, c, ∇lnπ)
				rtotal += reward_history[i]
			end
			rewards[ep] = rtotal
			steps[ep] = nsteps
		end
	end
	return (;episode_rewards = rewards, episode_steps = steps, policy_parameters = policy_params, value_parameters = value_params, policy_and_value_components...)
end

# ╔═╡ 4d4ae57b-afc3-44f9-b6fc-892f59f82921
#version of reinforce for general function approximation
function one_step_actor_critic!(policy_params, value_params, mdp::StateMDP{T, S, A, PTF, F1, F2, F3}, γ::T, max_episodes::Integer, max_steps::Integer, feature_vector, update_feature_vector!::Function, value_function::Function, ∇v̂, update_value_gradient!::Function, ∇lnπ; α_w::T = one(T)/10, α_θ::T = one(T)/10, policy = zeros(T, length(mdp.actions)), eligibility_vector_kwargs...) where {T<:Real, S, A, PTF, F1, F2, F3}
	episode_steps = Vector{Int64}()
	episode_rewards = Vector{T}()

	#initialize variables
	ep = 1
	step = 1
	rtot = zero(T)
	c = one(T)
	s = mdp.initialize_state()
	update_feature_vector!(feature_vector, s)

	# @info "initial value params: $value_params"

	policy_args = form_policy_args(policy_params)
	
	while (ep <= max_episodes) && (step <= max_steps)
		
		v̂ = update_value_gradient!(∇v̂, feature_vector, value_params)
		update_policy_dist!(policy, feature_vector, policy_params, policy_args...)
		i_a = sample_action(policy)
		policy_dist = update_eligibility_vector!(∇lnπ, feature_vector, i_a, policy_params; eligibility_vector_kwargs...)
	
		(r, s′) = mdp.ptf(s, i_a)
		rtot += r
		step += 1

		if mdp.isterm(s′)
			push!(episode_steps, step)
			push!(episode_rewards, rtot)
			v̂′ = zero(T)
			ep += 1
			rtot = zero(T)
			c = one(T)
			s = mdp.initialize_state()
			update_feature_vector!(feature_vector, s)
		else
			update_feature_vector!(feature_vector, s′)
			v̂′ = value_function(feature_vector, value_params)
			s = s′
			c *= γ
		end
		
		δ = r + γ*v̂′ - v̂

		# @info "About to update value params with gradient $∇v̂ and constant $(α_w * δ)"
		
		update_params_with_gradient!(value_params, α_w*δ, ∇v̂)
		# @info "About to update policy params with eligibility vector $∇lnπ and constant $(α_θ*c*δ)"
		update_params_with_gradient!(policy_params, α_θ*c*δ, ∇lnπ)
		# @info "policy params after $step updates: $policy_params"
		# @info "value params after $step updates: $value_params"
	end

	policy_and_value_components = form_policy_and_value_function(mdp, feature_vector, update_feature_vector!, policy_params, value_params)

	return (;episode_steps = episode_steps, episode_rewards = episode_rewards, policy_parameters = policy_params, value_parameters = value_params, policy_and_value_components...)
end

# ╔═╡ 57e5e12a-b722-4ea3-ab3b-e5711029e640
one_step_actor_critic_linear(mdp::StateMDP{T, S, A, PTF, F1, F2, F3}, γ::T, max_episodes::Integer, max_steps::Integer, feature_vector, update_feature_vector!::Function; init_value::T = zero(T), policy_params::Matrix{T} = initialize_linear_parameters(feature_vector, mdp, init_value), value_params::Vector{T} = initialize_linear_parameters(feature_vector, init_value), kwargs...) where {T<:Real, S, A, PTF, F1, F2, F3} = one_step_actor_critic!(policy_params, value_params, mdp, γ, max_episodes, max_steps, feature_vector, update_feature_vector!, linear_value_function, deepcopy(feature_vector), update_linear_value_gradient!, LinearEligibilityVector(feature_vector, policy_params); kwargs...)

