# ╔═╡ 266d2234-26c8-43f1-9e75-49440a230ed6
#version of reinforce for general function approximation
function actor_critic_with_eligibility_traces!(policy_params::P1, value_params::P2, mdp::StateMDP{T, S, A, PTF, F1, F2, F3}, γ::T, λ_θ::T, λ_w::T, max_episodes::Integer, max_steps::Integer, feature_vector, update_feature_vector!::Function, value_function::Function, ∇v̂, update_value_gradient!::Function, ∇lnπ; α_w::T = one(T)/10, α_θ::T = one(T)/10, policy::Vector{T} = zeros(T, length(mdp.actions)), z_θ::P1 = copy(policy_params), z_w::P2 = copy(value_params), trace_type::AbstractEligibilityTrace = AccumulatingTrace(), eligibility_vector_kwargs...) where {P1, P2, T<:Real, S, A, PTF, F1, F2, F3}
	episode_steps = Vector{Int64}()
	episode_rewards = Vector{T}()

	#initialize variables
	ep = 1
	step = 1
	rtot = zero(T)
	c = one(T)
	zero_trace!(z_θ)
	zero_trace!(z_w)
	policy_args = form_policy_args(policy_params)
	
	s = mdp.initialize_state()
	update_feature_vector!(feature_vector, s)
	
	while (ep <= max_episodes) && (step <= max_steps)
		v̂ = update_value_gradient!(∇v̂, feature_vector, value_params)

		decay_trace!(z_w, λ_w*γ)
		decay_trace!(z_θ, λ_θ*γ)
		
		update_trace_with_gradient!(z_w, ∇v̂, trace_type)
		apply_dutch_trace!(z_w, -α_w*γ*λ_w, feature_vector, value_function, ∇v̂, trace_type)
		
		update_policy_dist!(policy, feature_vector, policy_params, policy_args...)
		i_a = sample_action(policy)
		update_eligibility_vector!(∇lnπ, feature_vector, i_a, policy_params; eligibility_vector_kwargs...)
	
		(r, s′) = mdp.ptf(s, i_a)
		rtot += r
		step += 1

		terminated = mdp.isterm(s′)

		if terminated
			push!(episode_steps, step)
			push!(episode_rewards, rtot)
			v̂′ = zero(T)
			rtot = zero(T)
			ep += 1
			s = mdp.initialize_state()
			update_feature_vector!(feature_vector, s)
		else
			update_feature_vector!(feature_vector, s′)
			v̂′ = value_function(feature_vector, value_params)
			s = s′
		end
		
		δ = r + γ*v̂′ - v̂

		update_params_with_gradient!(z_θ, c, ∇lnπ)
		
		update_params_with_gradient!(value_params, α_w*δ, z_w)
		update_params_with_gradient!(policy_params, α_θ*δ, z_θ)

		if terminated
			zero_trace!(z_θ)
			zero_trace!(z_w)
			c = one(T)
		else
			c *= γ
		end
	end

	policy_and_value_components = form_policy_and_value_function(mdp, feature_vector, update_feature_vector!, policy_params, value_params)

	return (;episode_steps = episode_steps, episode_rewards = episode_rewards, policy_parameters = policy_params, value_parameters = value_params, traces = (z_θ, z_w), policy_and_value_components...)
end

# ╔═╡ eb330654-68d2-4ccd-80af-be079ee94008
#version of reinforce for general function approximation
function actor_critic_with_eligibility_traces!(policy_params::P1, value_params::P2, mdp::StateMDP{T, S, A, PTF, F1, F2, F3}, λ_θ::T, λ_w::T, num_steps::Integer, feature_vector, update_feature_vector!::Function, value_function::Function, ∇v̂, update_value_gradient!::Function, ∇lnπ; α_w::T = one(T)/10, α_θ::T = one(T)/10, α_r̄::T = one(T)/10, policy::Vector{T} = zeros(T, length(mdp.actions)), z_θ::P1 = copy(policy_params), z_w::P2 = copy(value_params), trace_type::AbstractEligibilityTrace = AccumulatingTrace(), eligibility_vector_kwargs...) where {P1, P2, T<:Real, S, A, PTF, F1, F2, F3}
	reward_history = zeros(T, num_steps)
	average_reward_history = zeros(T, num_steps)

	#initialize variables
	zero_trace!(z_θ)
	zero_trace!(z_w)
	policy_args = form_policy_args(policy_params)
	r̄ = zero(T)
	
	s = mdp.initialize_state()
	update_feature_vector!(feature_vector, s)
	
	for step in 1:num_steps
		v̂ = update_value_gradient!(∇v̂, feature_vector, value_params)

		decay_trace!(z_w, λ_w)
		decay_trace!(z_θ, λ_θ)
		
		update_trace_with_gradient!(z_w, ∇v̂, trace_type)
		apply_dutch_trace!(z_w, -α_w*λ_w, feature_vector, value_function, ∇v̂, trace_type)
		
		update_policy_dist!(policy, feature_vector, policy_params, policy_args...)
		i_a = sample_action(policy)
		update_eligibility_vector!(∇lnπ, feature_vector, i_a, policy_params; eligibility_vector_kwargs...)
		update_params_with_gradient!(z_θ, one(T), ∇lnπ)
		
		(r, s′) = mdp.ptf(s, i_a)
		
		reward_history[step] = r
		average_reward_history[step] = r̄

		mdp.isterm(s′) && error("$s′ is a terminal state and this method only applies to continuing tasks")

	
		update_feature_vector!(feature_vector, s′)
		v̂′ = value_function(feature_vector, value_params)
		s = s′

		δ = r - r̄ + v̂′ - v̂
		r̄ += α_r̄*δ
		
		update_params_with_gradient!(value_params, α_w*δ, z_w)
		update_params_with_gradient!(policy_params, α_θ*δ, z_θ)
	end

	policy_and_value_components = form_policy_and_value_function(mdp, feature_vector, update_feature_vector!, policy_params, value_params)

	return (;reward_history = reward_history, average_reward_history = average_reward_history, policy_parameters = policy_params, value_parameters = value_params, traces = (z_θ, z_w), policy_and_value_components...)
end

# ╔═╡ 740a3f41-9302-481d-b373-762c0dea8eff
begin
	function update_gaussian_eligibility_vector!(∇lnπ::BinaryGaussianEligibilityVector{T, T, T, B}, dist_params::Vector{T}, x::B, action::T, policy_params::Matrix{T}) where {T<:Real, B<:BinaryFeatureVector}
		∇lnπ.binary_features = x
		∇lnπ.a = action
		∇lnπ.μ = first(dist_params)
		∇lnπ.σ = exp(last(dist_params))
		# isapprox(∇lnπ.σ, 0f0) && @info "with distribution params $dist_params having 0 result for σ of $∇lnπ.σ"
		# isinf(∇lnπ.σ) && @info "with distribution params $dist_params having inf result for σ of $∇lnπ.σ"
		# isnan(∇lnπ.σ) && @info "with distribution params $dist_params having nan result for σ of $∇lnπ.σ"
		return ∇lnπ
	end

	function update_gaussian_eligibility_vector!(∇lnπ::BinaryGaussianEligibilityVector{T, NTuple{N, T}, Vector{T}, B}, dist_params::Vector{T}, x::B, action::NTuple{N, T}, policy_params::Matrix{T}) where {T<:Real, N, B<:BinaryFeatureVector}
		∇lnπ.binary_features = x
		∇lnπ.a = action
		for i in 1:N
			∇lnπ.μ[k] = dist_params[k]
			∇lnπ.σ[k] = exp(dist_params[k+N])
		end
		return ∇lnπ
	end
end

# ╔═╡ d41f1dd1-45fe-4456-9a01-ed47fd6704a7
begin
	function update_beta_eligibility_vector!(∇lnπ::BinaryBetaEligibilityVector{T, T, T, B}, dist_params::Vector{T}, x::B, action::T, policy_params::Matrix{T}) where {T<:Real, B<:BinaryFeatureVector}
		# @info "Beta eligibility vector is $∇lnπ"
		∇lnπ.binary_features = x
		∇lnπ.a = action
		∇lnπ.α = exp(first(dist_params))
		∇lnπ.β = exp(last(dist_params))
		# @info "Beta eligibility vector updated to $∇lnπ"
		return ∇lnπ
	end

	function update_beta_eligibility_vector!(∇lnπ::BinaryBetaEligibilityVector{T, NTuple{N, T}, Vector{T}, B}, dist_params::Vector{T}, x::B, action::NTuple{N, T}, policy_params::Matrix{T}) where {T<:Real, N, B<:BinaryFeatureVector}
		∇lnπ.binary_features = x
		∇lnπ.a = action
		for i in 1:N
			∇lnπ.α[k] = exp(dist_params[k])
			∇lnπ.β[k] = exp(dist_params[k+N])
		end
		return ∇lnπ
	end
end

# ╔═╡ 9ae58dd6-3cde-4943-9ac1-bd9d4f7d690c
begin
	function update_squashed_gaussian_eligibility_vector!(∇lnπ::BinarySquashedGaussianEligibilityVector{T, T, T, B}, dist_params::Vector{T}, x::B, action::T, policy_params::Matrix{T}) where {T<:Real, B<:BinaryFeatureVector}
		∇lnπ.binary_features = x
		∇lnπ.a = action
		∇lnπ.μ = first(dist_params)
		∇lnπ.σ = exp(last(dist_params))
		return ∇lnπ
	end

	function update_squashed_gaussian_eligibility_vector!(∇lnπ::BinarySquashedGaussianEligibilityVector{T, NTuple{N, T}, Vector{T}, B}, dist_params::Vector{T}, x::B, action::NTuple{N, T}, policy_params::Matrix{T}) where {T<:Real, N, B<:BinaryFeatureVector}
		∇lnπ.binary_features = x
		∇lnπ.a = action
		for i in 1:N
			∇lnπ.μ[k] = dist_params[k]
			∇lnπ.σ[k] = exp(dist_params[k+N])
		end
		return ∇lnπ
	end
end

# ╔═╡ f545c800-0bf3-491f-9d7d-42341cfdb573
function form_state_continuous_policy_function(update_feature_vector!::Function, update_action_preferences!::Function)
	function π!(x, action_preferences, s, params)
		# @info "Updating feature vector with state $(s)"
		update_feature_vector!(x, s)
		update_action_preferences!(action_preferences, x, params)
		# @info "Action distribution is $action_preferences"
		return action_preferences
	end
end

# ╔═╡ 5b868eba-c1af-49f6-8f93-79b78c319a6f
#version of reinforce for general function approximation
function reinforce_with_baseline_monte_carlo_control!(policy_params, ∇lnπ, value_params, ∇v̂, mdp::ContinuousMDP{T, S, A, PTF, F1, F2, F3}, update_action_distribution!::Function, action_dist_params::Vector{T}, action_sampler::Function, update_eligibility_vector!::Function, x, update_feature_vector!::Function, value_function::Function, update_value_gradient!::Function, max_episodes::Integer; α_w::T = one(T)/10, α_θ::T = one(T)/10, γ::T = one(T), epkwargs...) where {T<:Real, S, A, PTF, F1, F2, F3}
	rewards = Vector{Union{T, Missing}}(undef, max_episodes)
	steps = Vector{Union{Int64, Missing}}(undef, max_episodes)
	
	π! = form_state_continuous_policy_function(update_feature_vector!, update_action_distribution!)
	π(s) = π!(x, action_dist_params, s, policy_params)
	π_sample(s) = action_sampler(π(s))

	v! = form_state_value_function(update_feature_vector!, value_function)
	estimate_state_value(s) = v!(x, s, value_params)

	state_history, action_history, reward_history, _, _ = runepisode(mdp, π_sample, max_steps = 0) #initialize variables to update episodes
	for i in eachindex(rewards)
		# @info "On episode $i of $max_episodes"
		state_history, action_history, reward_history, sterm, nsteps = runepisode!((state_history, action_history, reward_history), mdp, π_sample, epkwargs...)
		if mdp.isterm(sterm) #if an episode does not terminate properly because the max steps have been reached then do not perform any learning updates
			g = zero(T)
			rtotal = zero(T)
			#iterate through episode beginning at the end
			for i in nsteps:-1:1
				g = (γ * g) + reward_history[i]
				update_feature_vector!(x, state_history[i])
				v̂ = value_function(x, value_params)
				δ = g - v̂
				update_value_gradient!(∇v̂, x, value_params)
				c = α_w*δ
				update_params_with_gradient!(value_params, c, ∇v̂)
				update_eligibility_vector!(∇lnπ, action_dist_params, x, action_history[i], policy_params)
				c = α_θ * γ^(i-1) * δ
				update_params_with_gradient!(policy_params, c, ∇lnπ)
				rtotal += reward_history[i]
			end
			rewards[i] = rtotal
			steps[i] = nsteps
		end
	end

	π2(s; feature_vector = deepcopy(x), action_dist_params = copy(action_dist_params)) = π!(feature_vector, action_dist_params, s, policy_params)
	π_sample2(s; kwargs...) = action_sampler(π2(s; kwargs...))
	function policy_and_value(s::S)
		π!(x, action_dist_params, s, policy_params)
		v̂ = value_function(x, value_params)
		return (action_distribution_parameters = action_dist_params, sampler_function = () -> action_sampler(action_dist_params), state_value_estimate = v̂)
	end
		
	return (episode_rewards = rewards, episode_steps = steps, policy_function = π2, policy_sample_action = π_sample2, policy_parameters = policy_params, estimate_state_value = estimate_state_value, value_parameters = value_params, policy_and_value = policy_and_value)
end

# ╔═╡ d8bac85f-3d77-4303-a2b6-2c1ccc040320
reinforce_monte_carlo_control_linear(mdp::StateMDP{T, S, A, P, F1, F2, F3}, γ::T, num_episodes::Integer, feature_vector, update_feature_vector!::Function; init_value::T = zero(T), policy_params::Matrix{T} = initialize_linear_parameters(feature_vector, mdp, init_value), kwargs...) where {T<:Real, S, A, P, F1, F2, F3} = reinforce_with_baseline_monte_carlo_control!(policy_params, nothing, mdp, γ, num_episodes, feature_vector, update_feature_vector!, Returns(zero(T)), deepcopy(feature_vector), Returns(nothing), LinearEligibilityVector(feature_vector, policy_params); kwargs...)

# ╔═╡ d037ea92-915c-4dc7-97c6-d006d92e088a
#=╠═╡
function figure_13_1(α_list; nruns = 100, num_episodes = 1_000, max_steps = 1_000)
	mdp = make_corridor_mdp(; reward = -1.)
	Random.seed!(45)
	function average_runs(α)
		1:nruns |> Map(_ -> reinforce_monte_carlo_control_linear(mdp, 1., num_episodes, deepcopy(corridor_feature_vector), update_corridor_feature!; policy_params = [0e0 3.7e0], α_θ = α, use_unfinished_episodes = true, max_steps = max_steps).episode_rewards) |> foldxt((a, b) -> a .+ b) |> v -> v ./ nruns
	end

	traces = [begin
		out = average_runs(α)
		scatter(x = 1:num_episodes, y = out, name = "α = 2^$(round(Int64, log2(α)))")
	end
	for α in α_list]

	baselinetrace = scatter(x = 1:num_episodes, y = fill(-2*sqrt(2) / (3*sqrt(2) - 4), num_episodes), name = "ideal value", line_dash = "dash", line_color = "gray")
	
	plot([baselinetrace; traces], Layout(yaxis_range = [-90, -10], yaxis_title = "Total reward on episode <br> (averaged over $nruns runs)", xaxis_title = "Episode", width = 800))
end
