# ╔═╡ 7d5c5e78-cdb9-4c1f-8b6d-53591f47ff00
function reinforce_with_baseline_monte_carlo_control_binary_features_gaussian_actions(mdp::ContinuousMDP{T, S, A, P, F1, F2, F3}, get_active_features::Function, num_features::Integer, max_episodes::Integer; policy_params::Matrix{T} = make_n_param_dist_policy_params(2, num_features, rand(A)), value_params::Vector{T} = zeros(T, num_features), kwargs...) where {T<:Real, S, N, A <: Union{T, NTuple{N, T}}, P, F1, F2, F3} 
	setup = setup_binary_gaussian_policy_arguments(mdp, get_active_features, num_features)
	reinforce_with_baseline_monte_carlo_control!(policy_params, setup.eligibility_vector, value_params, BinaryFeatureVector(num_features), mdp, update_binary_action_preferences!, setup.action_distribution_parameters, make_gaussian_sampler(rand(A)), update_gaussian_eligibility_vector!, setup.feature_vector, setup.update_feature_vector!, binary_value_function, update_binary_value_gradient!, max_episodes; kwargs...)
end

# ╔═╡ d5020a8d-1dd7-403c-9d1f-665b95543943
reinforce_with_baseline_monte_carlo_control_linear_features_gaussian_actions(mdp::ContinuousMDP{T, S, A, P, F1, F2, F3}, update_feature_vector!::Function, num_features::Integer, max_episodes::Integer; policy_params::Matrix{T} = make_n_param_dist_policy_params(2, num_features, rand(A)), value_params::Vector{T} = zeros(T, num_features), x = zeros(T, num_features), action_dist_params::Vector{T} = make_gaussian_params(rand(A)), kwargs...) where {T<:Real, S, N, A<:Union{T, NTuple{N, T}}, P, F1, F2, F3} = reinforce_with_baseline_monte_carlo_control!(policy_params, copy(policy_params), value_params, copy(value_params), mdp, update_linear_action_preferences!, action_dist_params, make_gaussian_sampler(rand(A)), update_gaussian_eligibility_vector!, x, update_feature_vector!, linear_value_function, update_linear_value_gradient!, max_episodes; kwargs...)

# ╔═╡ 2be8a812-4f21-4fe8-a2de-50497db0345a
md"""
### *Actor-Critic Implementation for Continuous Action Spaces*
"""

# ╔═╡ 056a8adc-92f4-4b33-90d9-4b3b4026bbbc
begin
	function update_traces_with_gradient!(c::T, z_θ::Matrix{T}, ∇θ::BinaryGaussianEligibilityVector{T, T, T, B}) where {T<:Real, B<:BinaryFeatureVector}
		c1 = ∇θ.a - ∇θ.μ
		c2 = ∇θ.σ^(-2)
		# isnan(c2) && @info "warning σ of $∇θ.σ is causing nan results"
		# isinf(c2) && @info "warning σ of $∇θ.σ is causing inf results"
		c3 = c1 * c2
		c4 = c3*c1 - one(T)
		z_θ .*= c
		@inbounds @simd for j in 1:∇θ.binary_features.num_features
			i = ∇θ.binary_features.active_features[j]
			z_θ[i, 1] += c3
		end
	
		@inbounds @simd for j in 1:∇θ.binary_features.num_features
			i = ∇θ.binary_features.active_features[j]
			z_θ[i, 2] += c4
		end
		return z_θ
	end

	function update_traces_with_gradient!(c::T, z_θ::Matrix{T}, ∇θ::BinaryBetaEligibilityVector{T, T, T, B}) where {T<:Real, B<:BinaryFeatureVector}
		c1 = digamma(∇θ.α + ∇θ.β)
		δ1 = ∇θ.α*(log(∇θ.a) + c1 - digamma(∇θ.α))
		z_θ .*= c
		@inbounds @simd for j in 1:∇θ.binary_features.num_features
			i = ∇θ.binary_features.active_features[j]
			z_θ[i, 1] += δ1
		end

		δ2 = ∇θ.β*(log(one(T) - ∇θ.a) + c1 - digamma(∇θ.β))
		@inbounds @simd for j in 1:∇θ.binary_features.num_features
			i = ∇θ.binary_features.active_features[j]
			z_θ[i, 2] += δ2
		end
		return z_θ
	end

	function update_traces_with_gradient!(c::T, z_θ::Matrix{T}, ∇θ::BinarySquashedGaussianEligibilityVector{T, T, T, B}) where {T<:Real, B<:BinaryFeatureVector}
		c1 = atanh(∇θ.a / ∇θ.amax) - ∇θ.μ
		c2 = ∇θ.σ^(-2)
		# isnan(c2) && @info "warning σ of $∇θ.σ is causing nan results"
		# isinf(c2) && @info "warning σ of $∇θ.σ is causing inf results"
		c3 = c1 * c2
		c4 = c3*c1 - one(T)
		z_θ .*= c
		@inbounds @simd for j in 1:∇θ.binary_features.num_features
			i = ∇θ.binary_features.active_features[j]
			z_θ[i, 1] += c3
		end
	
		@inbounds @simd for j in 1:∇θ.binary_features.num_features
			i = ∇θ.binary_features.active_features[j]
			z_θ[i, 2] += c4
		end
		return z_θ
	end

	function update_traces_with_gradient!(a::T, z_θ::Matrix{T}, b::T, ∇θ::BinaryGaussianEligibilityVector{T, T, T, B}) where {T<:Real, B<:BinaryFeatureVector}
		c1 = ∇θ.a - ∇θ.μ
		c2 = ∇θ.σ^(-2)
		# isnan(c2) && @info "warning σ of $∇θ.σ is causing nan results"
		# isinf(c2) && @info "warning σ of $∇θ.σ is causing inf results"
		c3 = c1 * c2
		c4 = c3*c1 - one(T)
		z_θ .*= a
		δ1 = b*c3
		@inbounds @simd for j in 1:∇θ.binary_features.num_features
			i = ∇θ.binary_features.active_features[j]
			z_θ[i, 1] += δ1
		end

		δ2 = b*c4
		@inbounds @simd for j in 1:∇θ.binary_features.num_features
			i = ∇θ.binary_features.active_features[j]
			z_θ[i, 2] += δ2
		end
		return z_θ
	end

	function update_traces_with_gradient!(a::T, z_θ::Matrix{T}, b::T, ∇θ::BinarySquashedGaussianEligibilityVector{T, T, T, B}) where {T<:Real, B<:BinaryFeatureVector}
		c1 = atanh(∇θ.a / ∇θ.amax) - ∇θ.μ
		c2 = ∇θ.σ^(-2)
		# isnan(c2) && @info "warning σ of $∇θ.σ is causing nan results"
		# isinf(c2) && @info "warning σ of $∇θ.σ is causing inf results"
		c3 = c1 * c2
		c4 = c3*c1 - one(T)
		z_θ .*= a
		δ1 = b*c3
		@inbounds @simd for j in 1:∇θ.binary_features.num_features
			i = ∇θ.binary_features.active_features[j]
			z_θ[i, 1] += δ1
		end

		δ2 = b*c4
		@inbounds @simd for j in 1:∇θ.binary_features.num_features
			i = ∇θ.binary_features.active_features[j]
			z_θ[i, 2] += δ2
		end
		return z_θ
	end

	function update_traces_with_gradient!(a::T, z_θ::Matrix{T}, b::T, ∇θ::BinaryBetaEligibilityVector{T, T, T, B}) where {T<:Real, B<:BinaryFeatureVector}
		c1 = digamma(∇θ.α + ∇θ.β)
		z_θ .*= a
		δ1 = b*∇θ.α*(log(∇θ.a) + c1 - digamma(∇θ.α))
		@inbounds @simd for j in 1:∇θ.binary_features.num_features
			i = ∇θ.binary_features.active_features[j]
			z_θ[i, 1] += δ1
		end

		δ2 = b*∇θ.β*(log(one(T) - ∇θ.a) + c1 - digamma(∇θ.β))
		@inbounds @simd for j in 1:∇θ.binary_features.num_features
			i = ∇θ.binary_features.active_features[j]
			z_θ[i, 2] += δ2
		end
		return z_θ
	end


	function update_traces_with_gradient!(a::T, z_θ::Matrix{T}, ∇θ::BinaryGaussianEligibilityVector{T, NTuple{N, T}, Vector{T}, B}) where {T<:Real, N, B<:BinaryFeatureVector}
		z_θ .*= a
		for k in 1:N
			c1 = ∇θ.a[k] - ∇θ.μ[k]
			c2 = ∇θ.σ[k] ^-2
			# isnan(c2) && @info "warning σ of $∇θ.σ is causing nan results"
			# isinf(c2) && @info "warning σ of $∇θ.σ is causing inf results"
			c3 = c1 * c2
			c4 = c3*c1 - one(T)
			
			@inbounds @simd for i in 1:size(θ, 1)
				θ[i, k] += c3
			end
		
			@inbounds @simd for i in 1:size(θ, 1)
				θ[i, k+N] += c4
			end
		end
		return θ
	end

	function update_traces_with_gradient!(a::T, z_θ::Matrix{T}, ∇θ::BinaryBetaEligibilityVector{T, NTuple{N, T}, Vector{T}, B}) where {T<:Real, N, B<:BinaryFeatureVector}
		z_θ .*= a
		for k in 1:N
			c1 = digamma(∇θ.α[k] + ∇θ.β[k])
			δ1 = ∇θ.α[k]*(log(∇θ.a[k]) + c1 - digamma(∇θ.α[k]))
			
			@inbounds @simd for i in 1:size(θ, 1)
				θ[i, k] += δ1
			end
			
			δ2 = ∇θ.β[k]*(log(one(T) - ∇θ.a[k]) + c1 - digamma(∇θ.β[k]))
			@inbounds @simd for i in 1:size(θ, 1)
				θ[i, k+N] += δ2
			end
		end
		return θ
	end

	function update_traces_with_gradient!(a::T, z_θ::Matrix{T}, b::T, ∇θ::BinaryGaussianEligibilityVector{T, NTuple{N, T}, Vector{T}, B}) where {T<:Real, N, B<:BinaryFeatureVector}
		z_θ .*= a
		for k in 1:N
			c1 = ∇θ.a[k] - ∇θ.μ[k]
			c2 = ∇θ.σ[k] ^-2
			isnan(c2) && @info "warning σ of $∇θ.σ is causing nan results"
			isinf(c2) && @info "warning σ of $∇θ.σ is causing inf results"
			c3 = c1 * c2
			c4 = c3*c1 - one(T)
			δ1 = b*c3
			
			@inbounds @simd for i in 1:size(θ, 1)
				θ[i, k] += δ1
			end
		
			δ2 = b*c4
			@inbounds @simd for i in 1:size(θ, 1)
				θ[i, k+N] += δ2
			end
		end
		return θ
	end

	function update_traces_with_gradient!(a::T, z_θ::Matrix{T}, b::T, ∇θ::BinaryBetaEligibilityVector{T, NTuple{N, T}, Vector{T}, B}) where {T<:Real, N, B<:BinaryFeatureVector}
		z_θ .*= a
		for k in 1:N
			c1 = digamma(∇θ.α[k] + ∇θ.β[k])
			δ1 = b*∇θ.α[k]*(log(∇θ.a[k]) + c1 - digamma(∇θ.α[k]))
			
			@inbounds @simd for i in 1:size(θ, 1)
				θ[i, k] += δ1
			end
			
			δ2 = b*∇θ.β[k]*(log(one(T) - ∇θ.a[k]) + c1 - digamma(∇θ.β[k]))
			@inbounds @simd for i in 1:size(θ, 1)
				θ[i, k+N] += δ2
			end
		end
		return θ
	end
end

# ╔═╡ 11b9beea-b0cd-45eb-84c6-151728894df0
function form_state_and_policy_function_outputs(update_feature_vector!::Function, update_action_distribution!::Function, action_dist_params::Vector{T}, action_sampler::Function, value_function::Function, feature_vector, policy_params, value_params) where T<:Real
	π! = form_state_continuous_policy_function(update_feature_vector!, update_action_distribution!)
	π(s) = π!(feature_vector, action_dist_params, s, policy_params)
	π_sample(s) = action_sampler(π(s))

	v! = form_state_value_function(update_feature_vector!, value_function)
	estimate_state_value(s; x = deepcopy(feature_vector)) = v!(x, s, value_params)

	function policy_and_value(s; x = deepcopy(feature_vector), action_dist_params = copy(action_dist_params))
		π!(x, action_dist_params, s, policy_params)
		v̂ = value_function(x, value_params)
		return (action_distribution_parameters = action_dist_params, state_value_estimate = v̂)
	end

	(policy_function = π, policy_sample_action = π_sample, estimate_state_value = estimate_state_value, policy_and_value = policy_and_value)
end

# ╔═╡ b71145a4-2614-4f62-bfd2-7d5d1fecec56
#version of reinforce for general function approximation
function actor_critic_with_eligibility_traces!(policy_params::P1, ∇lnπ, value_params::P2, ∇v̂, mdp::ContinuousMDP{T, S, A, PTF, F1, F2, F3}, λ_θ::T, λ_w::T, update_action_distribution!::Function, action_dist_params::Vector{T}, action_sampler::Function, update_eligibility_vector!::Function, x, update_feature_vector!::Function, value_function::Function, update_value_gradient!::Function, max_episodes::Integer, max_steps::Integer; α_w::T = one(T)/10, α_θ::T = one(T)/10, γ::T = one(T), z_θ::P1 = deepcopy(policy_params), z_w::P2 = deepcopy(value_params), save_step_rewards = false) where {P1, P2, T<:Real, S, A, PTF, F1, F2, F3}
	step_rewards = Vector{T}()
	episode_steps = Vector{Int64}()
	episode_rewards = Vector{T}()

	#initialize variables
	ep = 1
	step = 1
	rtot = zero(T)
	c = one(T)
	zero_params!(z_θ)
	zero_params!(z_w)
	
	s = mdp.initialize_state()
	update_feature_vector!(x, s)
	
	while (ep <= max_episodes) && (step <= max_steps)
		update_value_gradient!(∇v̂, x, value_params)
		v̂ = value_function(x, value_params)
		update_action_distribution!(action_dist_params, x, policy_params)
		a = action_sampler(action_dist_params)
		if bad_continuous_action(a)
			@info "terminating after $step steps and episode $ep due to invalid continuous action $a taken in state $s with action distribution parameters $action_dist_params"
			push!(episode_steps, max_steps)
			push!(episode_rewards, typemin(T))
			break
		end
		update_eligibility_vector!(∇lnπ, action_dist_params, x, a, policy_params)
	
		(r, s′) = mdp.ptf(s, a)
		rtot += r
		save_step_rewards && push!(step_rewards, r)
		step += 1

		if mdp.isterm(s′)
			push!(episode_steps, step)
			push!(episode_rewards, rtot)
			v̂′ = zero(T)
			rtot = zero(T)
			zero_params!(z_θ)
			zero_params!(z_w)
			ep += 1
			c = one(T)
			s = mdp.initialize_state()
			update_feature_vector!(x, s)
		else
			update_feature_vector!(x, s′)
			v̂′ = value_function(x, value_params)
			s = s′
			c *= γ
		end
		
		δ = r + γ*v̂′ - v̂

		update_traces_with_gradient!(γ*λ_w, z_w, ∇v̂)
		update_traces_with_gradient!(γ*λ_θ, z_θ, c, ∇lnπ)
		
		update_params_with_gradient!(value_params, α_w*δ, z_w)
		update_params_with_gradient!(policy_params, α_θ*c*δ, z_θ)
	end

	function_outputs = form_state_and_policy_function_outputs(update_feature_vector!, update_action_distribution!, action_dist_params, action_sampler, value_function, x, policy_params, value_params)

	return (;step_rewards = step_rewards, episode_steps = episode_steps, episode_rewards = episode_rewards, policy_parameters = policy_params, value_parameters = value_params, function_outputs...)
end

# ╔═╡ 4da20fd7-b897-4f26-bf2a-f08d66ddf90f
#version of reinforce for general function approximation
function actor_critic_with_eligibility_traces!(policy_params::P1, ∇lnπ, value_params::P2, ∇v̂, mdp::ContinuousMDP{T, S, A, PTF, F1, F2, F3}, λ_θ::T, λ_w::T, update_action_distribution!::Function, action_dist_params::Vector{T}, action_sampler::Function, update_eligibility_vector!::Function, x, update_feature_vector!::Function, value_function::Function, update_value_gradient!::Function, max_steps::Integer; α_w::T = one(T)/10, α_θ::T = one(T)/10, α_r̄ = one(T)/10, z_θ::P1 = deepcopy(policy_params), z_w::P2 = deepcopy(value_params), save_step_rewards = false) where {P1, P2, T<:Real, S, A, PTF, F1, F2, F3}
	step_rewards = Vector{T}()

	#initialize variables
	step = 1
	rtot = zero(T)
	r̄ = zero(T)
	c = one(T)
	zero_params!(z_θ)
	zero_params!(z_w)
	
	s = mdp.initialize_state()
	update_feature_vector!(x, s)
	
	while step <= max_steps
		update_value_gradient!(∇v̂, x, value_params)
		v̂ = value_function(x, value_params)
		update_action_distribution!(action_dist_params, x, policy_params)
		a = action_sampler(action_dist_params)
		if bad_continuous_action(a)
			@info "terminating after $step steps due to invalid continuous action $a taken in state $s with action distribution parameters $action_dist_params"
			push!(episode_steps, max_steps)
			push!(episode_rewards, typemin(T))
			break
		end
		update_eligibility_vector!(∇lnπ, action_dist_params, x, a, policy_params)
	
		(r, s′) = mdp.ptf(s, a)
		rtot += r
		save_step_rewards && push!(step_rewards, r)
		step += 1

		mdp.isterm(s′) && error("$s′ is a terminal state and this method only applies to continuing tasks")
		
		update_feature_vector!(x, s′)
		v̂′ = value_function(x, value_params)	
		δ = r - r̄ + v̂′ - v̂
		r̄ += α_r̄*δ

		update_traces_with_gradient!(γ*λ_w, z_w, ∇v̂)
		update_traces_with_gradient!(γ*λ_θ, z_θ, c, ∇lnπ)
		
		update_params_with_gradient!(value_params, α_w*δ, z_w)
		update_params_with_gradient!(policy_params, α_θ*c*δ, z_θ)

		s = s′
	end

	function_outputs = form_state_and_policy_function_outputs(update_feature_vector!, update_action_distribution!, action_dist_params, action_sampler, value_function, x, policy_params, value_params)

	return (;step_rewards = step_rewards, total_reward = rtot, policy_parameters = policy_params, value_parameters = value_params, function_outputs...)
end

# ╔═╡ 05bfd818-bf4e-4bda-baa9-5ba647867097
actor_critic_with_eligibility_traces_linear(mdp::StateMDP{T, S, A, PTF, F1, F2, F3}, γ::T, λ_θ::T, λ_w::T, max_episodes::Integer, max_steps::Integer, feature_vector, update_feature_vector!::Function; init_value::T = zero(T), policy_params::Matrix{T} = initialize_linear_parameters(feature_vector, mdp, init_value), value_params::Vector{T} = initialize_linear_parameters(feature_vector, init_value), kwargs...) where {T<:Real, S, A, PTF, F1, F2, F3} = actor_critic_with_eligibility_traces!(policy_params, value_params, mdp, γ, λ_θ, λ_w, max_episodes, max_steps, feature_vector, update_feature_vector!, linear_value_function, deepcopy(feature_vector), update_linear_value_gradient!, LinearEligibilityVector(feature_vector, policy_params); kwargs...)

# ╔═╡ 97b7ce3f-6d1e-41bc-ba07-50e8516a2d54
function actor_critic_with_eligibility_traces_fcann(mdp::StateMDP{T, S, A, P, F1, F2, F3}, γ::T, λ_θ::T, λ_w::T, max_episodes::Integer, max_steps::Integer, feature_vector, update_feature_vector!::Function, hidden_layers::Vector{Int64}; reslayers::Integer = 0, use_μP::Bool = true, policy_params::FCANNParams = initialize_fcann_params(feature_vector, hidden_layers, length(mdp.actions), reslayers, use_μP), value_params::FCANNParams = initialize_fcann_value_params(policy_params, use_μP), activation_list::Vector{Bool} = fill(true, length(hidden_layers)), l2::T = zero(T), dropout::T = zero(T), use_gpu::Bool = false, kwargs...) where {T<:Real, S, A, P, F1, F2, F3}
	value_setup = setup_fcann_value_arguments(value_params, l2, dropout, use_μP, activation_list)
	!use_gpu && return actor_critic_with_eligibility_traces!(policy_params, value_params, mdp, γ, λ_θ, λ_w, max_episodes, max_steps, feature_vector, update_feature_vector!, value_setup.value_function, value_setup.gradient, value_setup.update_gradient!, NonLinearEligibilityVector(feature_vector, policy_params; use_μP = use_μP); kwargs...)

	isempty(value_setup.gpu_args) && error("GPU backend is not available")
	d_policy_params = initialize_gpu_params(policy_params)
	d_value_params = initialize_fcann_value_params(d_policy_params, use_μP)
	gpu_feature_update! = setup_gpu_feature(feature_vector, update_feature_vector!)
	∇lnπ = NonLinearGPUEligibilityVector(value_setup.gpu_args.feature_vector, d_policy_params; use_μP = use_μP)
	output = actor_critic_with_eligibility_traces!(d_policy_params, d_value_params, mdp, γ, λ_θ, λ_w, max_episodes, max_steps, value_setup.gpu_args.feature_vector, gpu_feature_update!, value_setup.value_function, value_setup.gpu_args.gradient, value_setup.update_gradient!, ∇lnπ; kwargs...)
	FCANN.GPU2Host(policy_params.weights, d_policy_params.weights)
	FCANN.GPU2Host(value_params.weights, d_value_params.weights)
	cleanup_gpu_eligibility_vector(∇lnπ)
	value_setup.gpu_args.cleanup_vars()
	FCANN.clear_gpu_data(d_value_params.weights[1])
	FCANN.clear_gpu_data(d_value_params.weights[2])
	FCANN.clear_gpu_data(output.traces[1].weights[1])
	FCANN.clear_gpu_data(output.traces[1].weights[2])
	FCANN.clear_gpu_data(output.traces[2].weights[1])
	FCANN.clear_gpu_data(output.traces[2].weights[2])
	(;output..., policy_parameters = policy_params, value_parameters = value_params)
end

# ╔═╡ 4bc22ad6-75f7-4dc9-8bfe-9f5a99eb67ef
actor_critic_with_eligibility_traces_linear(mdp::StateMDP{T, S, A, PTF, F1, F2, F3}, λ_θ::T, λ_w::T, num_steps::Integer, feature_vector, update_feature_vector!::Function; init_value::T = zero(T), policy_params::Matrix{T} = initialize_linear_parameters(feature_vector, mdp, init_value), value_params::Vector{T} = initialize_linear_parameters(feature_vector, init_value), kwargs...) where {T<:Real, S, A, PTF, F1, F2, F3} = actor_critic_with_eligibility_traces!(policy_params, value_params, mdp, λ_θ, λ_w, num_steps, feature_vector, update_feature_vector!, linear_value_function, deepcopy(feature_vector), update_linear_value_gradient!, LinearEligibilityVector(feature_vector, policy_params); kwargs...)

